using System.Text.Json.Nodes;
namespace AetherGrid.Server;
public static class Operations
{
 public static void Map(WebApplication app,Store store,Security security,IConfiguration config){
 app.MapPost("/api/admin/password-recovery/{id}",(HttpContext c,string id)=>{Security.Operator(c);var token=Security.Random();store.Write(tx=>{tx.Need("user",id);foreach(var old in tx.All("recovery").Where(x=>x.S("username")==id))tx.Delete("recovery",old.S("id"));var hash=Security.Hash(token);tx.Put("recovery",hash,new JsonObject{["id"]=hash,["username"]=id,["expires_at"]=J.Epoch()+1200});tx.Event("recovery_issued",id,new JsonObject{["subject"]=Security.Actor(c).Subject});return true;});return new{token,expires_in_seconds=1200,delivery="operator must securely deliver; no email service"};});
 app.MapPost("/api/auth/recover",(JsonObject p)=>{J.Require(p.S("token").Length==64&&p.S("password").Length is >=16 and <=1024,"Invalid recovery request");var hash=Security.Hash(p.S("token"));var passwordHash=Security.Password(p.S("password"));return store.Write(tx=>{var r=tx.Get("recovery",hash);J.Require(r is not null&&r.N("expires_at")>J.Epoch(),"Invalid or expired recovery token",401);var u=tx.Need("user",r!.S("username"));J.Require(!u.B("disabled"),"Disabled account requires separate administrator review",403);u["password_hash"]=passwordHash;u["version"]=u.N("version")+1;tx.Put("user",u.S("username"),u);tx.Delete("recovery",hash);tx.Event("password_recovered",u.S("username"),new JsonObject{["all_sessions_revoked"]=true});return new{status="password_reset",all_sessions_revoked=true};});}).RequireRateLimiting("login");
 app.MapPost("/api/auth/change-password",(HttpContext c,JsonObject p)=>{var actor=Security.Actor(c);J.Require(actor.SessionId is not null,"Browser account required",403);J.Require(p.S("new_password").Length is >=16 and <=1024&&p.S("old_password").Length<=1024,"Invalid password");var hash=Security.Password(p.S("new_password"));return store.Write(tx=>{var u=tx.Need("user",actor.Subject);J.Require(Security.Verify(p.S("old_password"),u.S("password_hash")),"Current password incorrect",403);u["password_hash"]=hash;u["version"]=u.N("version")+1;tx.Put("user",actor.Subject,u);tx.Event("password_changed",actor.Subject,new JsonObject{["all_sessions_revoked"]=true});return new{status="password_changed",all_sessions_revoked=true};});});
 app.MapPost("/api/admin/api-keys/{id}/rotate",(HttpContext c,string id,JsonObject p)=>{Security.Operator(c);return store.Write(tx=>{var key=tx.Need("api_key",id);var next=p.S("new_digest");J.Require(!key.B("disabled")&&next.Length==64&&next.All(Uri.IsHexDigit)&&next!=id&&tx.Get("api_key",next) is null,"Invalid replacement digest",409);J.Require(p.N("expires_at")>J.Epoch()&&p.N("expires_at")<=J.Epoch()+90*86400,"Expiry must be within 90 days");var replacement=key.Copy();replacement["id"]=next;replacement["expires_at"]=p.N("expires_at");replacement["rotated_at"]=J.Now();key["disabled"]=true;tx.Put("api_key",id,key);tx.Put("api_key",next,replacement);tx.Event("api_key_rotated",key.S("subject"),new JsonObject{["old_digest"]=id,["new_digest"]=next,["subject"]=Security.Actor(c).Subject});return new{status="rotated",old_key_revoked=true};});});
 app.MapPost("/api/admin/api-keys/{id}/revoke",(HttpContext c,string id)=>{Security.Operator(c);return store.Write(tx=>{var key=tx.Need("api_key",id);key["disabled"]=true;tx.Put("api_key",id,key);tx.Event("api_key_revoked",key.S("subject"),new JsonObject{["digest"]=id});return new{status="revoked"};});});
 object Cleanup(bool apply)=>store.Write(tx=>{int count=0;foreach(var kind in new[]{"session","recovery","login_attempt"})foreach(var x in tx.All(kind)){var expired=kind=="login_attempt"?x.N("updated_at",x.N("locked_until"))>0&&x.N("updated_at",x.N("locked_until"))<J.Epoch()-86400:x.N("expires_at")<=J.Epoch();if(expired){count++;if(apply)tx.Delete(kind,kind=="login_attempt"?x.S("id"):x.S("id",kind=="session"?x.S("session_id"):""));}}if(apply)tx.Event("ephemeral_retention_applied","",new JsonObject{["deleted"]=count});return new{dry_run=!apply,eligible=count,preserved="all telemetry, evidence, replay cursors, financial obligations, ledger and audit outbox"};});
 app.MapGet("/api/admin/retention/preview",(HttpContext c)=>{Security.Operator(c);return Cleanup(false);});
 app.MapPost("/api/admin/retention/apply",(HttpContext c,JsonObject p)=>{Security.Operator(c);J.Require(p.B("acknowledged"),"Explicit acknowledgement required");return Cleanup(true);});
 app.MapGet("/api/admin/readiness",(HttpContext c)=>{Security.Operator(c);var alerts=store.Read(tx=>{var result=new List<object>();foreach(var b in tx.All("batch").Where(b=>b.S("status") is "InTransit" or "DistressedLiquidation" or "Rerouted")){var cursor=tx.Get("cursor",b.S("truck_id"));if(cursor is null||J.Epoch()-cursor.N("ts")>120)result.Add(new{code="telemetry_stale_or_missing",batch_id=b.S("id"),severity="critical"});}foreach(var x in tx.All("intent").Where(x=>x.S("state")=="pending"&&DateTimeOffset.UtcNow-DateTimeOffset.Parse(x.S("dispatched_at"))>TimeSpan.FromMinutes(5)))result.Add(new{code="reconciliation_overdue",batch_id=x.S("batch_id"),severity="critical"});return result;});return new{status=alerts.Count==0?"ready_for_supervised_software_use":"attention_required",database=store.Integrity(),alerts,production_certified=false,secure_cookies=security.SecureCookies};});
 }
}
